def shrink_types(types, max_typed_dict_size):
    if not types:
        return Any

    # Convert to list to handle various iterables
    types = list(types)

    # If all types are the same, return that type
    if len(set(types)) == 1:
        return types[0]

    # For multiple different types, return Union
    return Union[tuple(types)]
